#!/usr/bin/env python3
"""A small persistent HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024


class Store:
    """Thread-safe store whose mutations are durably written as one JSON file."""

    def __init__(self, path: Path) -> None:
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, Any]] = {}
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            return
        with self.path.open("r", encoding="utf-8") as stream:
            document = json.load(stream, parse_constant=self._reject_constant)
        if not isinstance(document, dict) or not isinstance(document.get("entries"), dict):
            raise ValueError("data file does not contain a valid store")
        now = time.time()
        changed = False
        for key, entry in document["entries"].items():
            if not isinstance(key, str) or not isinstance(entry, dict) or "value" not in entry:
                raise ValueError("data file contains an invalid entry")
            expires_at = entry.get("expires_at")
            if expires_at is not None and (
                isinstance(expires_at, bool)
                or not isinstance(expires_at, (int, float))
                or not math.isfinite(expires_at)
            ):
                raise ValueError("data file contains an invalid expiry")
            if expires_at is not None and expires_at <= now:
                changed = True
                continue
            self.entries[key] = {"value": entry["value"], "expires_at": expires_at}
        if changed:
            self._persist()

    @staticmethod
    def _reject_constant(value: str) -> None:
        raise ValueError(f"non-standard JSON number: {value}")

    def _persist(self) -> None:
        directory = self.path.parent
        directory.mkdir(parents=True, exist_ok=True)
        fd, temporary = tempfile.mkstemp(prefix=f".{self.path.name}.", suffix=".tmp", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(
                    {"entries": self.entries}, stream, ensure_ascii=False,
                    separators=(",", ":"), allow_nan=False,
                )
                stream.write("\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, self.path)
            try:
                directory_fd = os.open(directory, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                pass
        except BaseException:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise

    def _purge(self, now: float) -> bool:
        expired = [
            key for key, entry in self.entries.items()
            if entry["expires_at"] is not None and entry["expires_at"] <= now
        ]
        for key in expired:
            del self.entries[key]
        if expired:
            self._persist()
        return bool(expired)

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            self._purge(time.time())
            created = key not in self.entries
            self.entries[key] = {
                "value": value,
                "expires_at": None if ttl is None else time.time() + ttl,
            }
            self._persist()
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            self._purge(time.time())
            entry = self.entries.get(key)
            return (False, None) if entry is None else (True, entry["value"])

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge(time.time())
            if key not in self.entries:
                return False
            del self.entries[key]
            self._persist()
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._purge(time.time())
            return sorted(self.entries)


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: Store) -> None:
        self.store = store
        super().__init__(address, Handler)


class Handler(BaseHTTPRequestHandler):
    server: Server
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt: str, *args: Any) -> None:
        import sys
        print(f"{self.address_string()} - {fmt % args}", file=sys.stderr, flush=True)

    def send_error(self, code: int, message: str | None = None, explain: str | None = None) -> None:
        self._json(code, {"error": message or self.responses.get(code, ("Error",))[0]})

    def _json(self, status: int, body: Any | None = None) -> None:
        encoded = b"" if body is None else json.dumps(
            body, ensure_ascii=False, separators=(",", ":"), allow_nan=False
        ).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(encoded)))
        self.end_headers()
        if encoded and self.command != "HEAD":
            self.wfile.write(encoded)

    def _key(self, raw_path: str) -> str:
        prefix = "/v1/kv/"
        encoded = raw_path[len(prefix):]
        index = 0
        while index < len(encoded):
            if encoded[index] == "%":
                if index + 2 >= len(encoded) or any(c not in "0123456789abcdefABCDEF" for c in encoded[index + 1:index + 3]):
                    raise ValueError("invalid percent-encoding")
                index += 3
            else:
                index += 1
        try:
            key = unquote_to_bytes(encoded).decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError("key is not valid UTF-8") from error
        if not key or "/" in key:
            raise ValueError("key must be non-empty and must not contain '/'")
        return key

    def _read_json(self) -> Any:
        if self.headers.get("Transfer-Encoding"):
            raise RequestError(400, "transfer encoding is not supported")
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            raise RequestError(411, "Content-Length is required")
        try:
            length = int(raw_length)
        except ValueError as error:
            raise RequestError(400, "invalid Content-Length") from error
        if length < 0:
            raise RequestError(400, "invalid Content-Length")
        if length > MAX_BODY:
            self.close_connection = True
            raise RequestError(413, "request body exceeds 1 MiB")
        raw = self.rfile.read(length)
        try:
            return json.loads(raw.decode("utf-8"), parse_constant=Store._reject_constant)
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as error:
            raise RequestError(400, "malformed JSON") from error

    def _dispatch(self) -> None:
        path = urlsplit(self.path).path
        try:
            if self.command == "GET" and path == "/health":
                self._json(200, {"status": "ok"})
                return
            if self.command == "GET" and path == "/v1/keys":
                self._json(200, {"keys": self.server.store.keys()})
                return
            if path.startswith("/v1/kv/"):
                key = self._key(path)
                if self.command == "GET":
                    present, value = self.server.store.get(key)
                    self._json(200, {"key": key, "value": value}) if present else self._json(404, {"error": "key not found"})
                    return
                if self.command == "DELETE":
                    self._json(204) if self.server.store.delete(key) else self._json(404, {"error": "key not found"})
                    return
                if self.command == "PUT":
                    document = self._read_json()
                    if not isinstance(document, dict) or "value" not in document or not set(document) <= {"value", "ttl_seconds"}:
                        raise RequestError(400, "body must be an object containing value and optional ttl_seconds")
                    ttl = document.get("ttl_seconds")
                    if ttl is not None and (
                        isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                        or not math.isfinite(ttl) or ttl <= 0
                    ):
                        raise RequestError(400, "ttl_seconds must be a finite number greater than zero")
                    created = self.server.store.put(key, document["value"], ttl)
                    self._json(201 if created else 200, {"key": key, "value": document["value"]})
                    return
                self._json(405, {"error": "method not allowed"})
                return
            if path in {"/health", "/v1/keys"}:
                self._json(405, {"error": "method not allowed"})
                return
            self._json(404, {"error": "route not found"})
        except RequestError as error:
            self._json(error.status, {"error": error.message})
        except ValueError as error:
            self._json(400, {"error": str(error)})
        except (OSError, TypeError, OverflowError) as error:
            self.log_error("request failed: %s", error)
            self._json(500, {"error": "internal server error"})

    do_GET = _dispatch
    do_PUT = _dispatch
    do_DELETE = _dispatch
    do_POST = _dispatch
    do_PATCH = _dispatch
    do_OPTIONS = _dispatch
    do_HEAD = _dispatch


class RequestError(Exception):
    def __init__(self, status: int, message: str) -> None:
        self.status = status
        self.message = message
        super().__init__(message)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", type=Path, required=True)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    import sys
    args = parse_args()
    try:
        store = Store(args.data)
        server = Server((args.host, args.port), store)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        print(f"startup failed: {error}", file=sys.stderr, flush=True)
        return 1

    def stop(_signum: int, _frame: Any) -> None:
        threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever()
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
