import time
import unittest
from pathlib import Path
from urllib.parse import quote


class RunningServer:
    def __init__(self, data: Path):
        self.process = subprocess.Popen(
            [sys.executable, "server.py", "--host", "127.0.0.1", "--port", "0", "--data", str(data)],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
        )
        line = self.process.stdout.readline()
        if not line.startswith("LISTENING "):
            raise RuntimeError(f"server failed: {line} {self.process.stderr.read()}")
        self.port = int(line.split()[1])

    def request(self, method, path, body=None, headers=None):
        connection = http.client.HTTPConnection("127.0.0.1", self.port, timeout=3)
        payload = None if body is None else json.dumps(body)
        connection.request(method, path, payload, headers or {})
        response = connection.getresponse()
        raw = response.read()
        result = response.status, (json.loads(raw) if raw else None), response.getheader("Content-Type")
        connection.close()
        return result

    def close(self):
        self.process.terminate()
        self.process.wait(timeout=5)


class ServiceTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.data = Path(self.temp.name) / "data.json"
        self.server = RunningServer(self.data)

    def tearDown(self):
        self.server.close()
        self.temp.cleanup()

    def test_crud_keys_and_persistence(self):
        key = quote("hello world")
        self.assertEqual(self.server.request("PUT", f"/v1/kv/{key}", {"value": {"n": 1}})[0], 201)
        self.assertEqual(self.server.request("PUT", f"/v1/kv/{key}", {"value": [2]})[0], 200)
        self.assertEqual(self.server.request("GET", f"/v1/kv/{key}")[1], {"key": "hello world", "value": [2]})
        self.assertEqual(self.server.request("GET", "/v1/keys")[1], {"keys": ["hello world"]})
        self.server.close()
        self.server = RunningServer(self.data)
        self.assertEqual(self.server.request("GET", f"/v1/kv/{key}")[0], 200)
        self.assertEqual(self.server.request("DELETE", f"/v1/kv/{key}")[0], 204)
        self.assertEqual(self.server.request("GET", f"/v1/kv/{key}")[0], 404)

    def test_ttl_and_errors(self):
        self.assertEqual(self.server.request("PUT", "/v1/kv/short", {"value": 1, "ttl_seconds": .05})[0], 201)
        time.sleep(.08)
        self.assertEqual(self.server.request("GET", "/v1/kv/short")[0], 404)
        for body in ([], {}, {"value": 1, "ttl_seconds": 0}, {"value": 1, "ttl_seconds": True}):
            self.assertEqual(self.server.request("PUT", "/v1/kv/bad", body)[0], 400)
        self.assertEqual(self.server.request("POST", "/health", {})[0], 405)
        self.assertEqual(self.server.request("GET", "/unknown")[0], 404)

    def test_health_and_body_limit(self):
        status, body, content_type = self.server.request("GET", "/health")
        self.assertEqual((status, body, content_type), (200, {"status": "ok"}, "application/json"))
        connection = http.client.HTTPConnection("127.0.0.1", self.server.port, timeout=3)
        connection.request("PUT", "/v1/kv/x", b"", {"Content-Length": str(1024 * 1024 + 1)})
        response = connection.getresponse()
        self.assertEqual(response.status, 413)
        response.read()
        connection.close()


if __name__ == "__main__":
    unittest.main()
# Persistent HTTP key-value service

A dependency-free Python 3.11+ HTTP service with atomic JSON persistence, optional TTLs, and concurrent request handling.

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Port `0` asks the operating system for a free port; the service prints `LISTENING <port>` as its first stdout line. Diagnostics go to stderr.

The API provides `PUT`, `GET`, and `DELETE /v1/kv/{url-encoded-key}`, `GET /v1/keys`, and `GET /health`. PUT bodies have the form `{"value": <JSON value>, "ttl_seconds": <positive finite number>}`; `ttl_seconds` is optional. Request bodies are limited to 1 MiB.

Run the integration tests with:

```sh
python3 -m unittest -v
```

